INSERT INTO department (department_name, department_description, bed_capacity, floor_building, director_id) VALUES
('Επείγοντα Περιστατικά', 'Τμήμα αντιμετώπισης επειγόντων και οξέων περιστατικών. Λειτουργεί 24/7 με τμήμα triage.', 20, 'Κτίριο Α - Ισόγειο', NULL),
('Καρδιολογία', 'Διάγνωση και θεραπεία παθήσεων καρδιάς και αγγείων. Περιλαμβάνει Μονάδα Εμφραγμάτων.', 30, 'Κτίριο Α - 2ος Όροφος', NULL),
('Χειρουργική', 'Γενική χειρουργική για εκλεκτικές και επείγουσες επεμβάσεις κοιλιάς και θώρακα.', 25, 'Κτίριο Β - 1ος Όροφος', NULL),
('Ορθοπαιδική', 'Χειρουργική και συντηρητική αντιμετώπιση παθήσεων μυοσκελετικού συστήματος.', 25, 'Κτίριο Β - 2ος Όροφος', NULL),
('Νευρολογία', 'Διάγνωση και θεραπεία νευρολογικών παθήσεων όπως εγκεφαλικά, επιληψία, νόσος Parkinson.', 20, 'Κτίριο Α - 3ος Όροφος', NULL),
('Παθολογία', 'Εσωτερική ιατρική για ευρύ φάσμα παθήσεων. Μεγαλύτερο τμήμα του νοσοκομείου.', 40, 'Κτίριο Α - 1ος Όροφος', NULL),
('Πνευμονολογία', 'Διάγνωση και θεραπεία παθήσεων αναπνευστικού συστήματος.', 20, 'Κτίριο Γ - 1ος Όροφος', NULL),
('Γαστρεντερολογία', 'Παθήσεις πεπτικού συστήματος. Περιλαμβάνει ενδοσκοπικό τμήμα.', 20, 'Κτίριο Γ - 2ος Όροφος', NULL),
('Ουρολογία', 'Χειρουργική και παθολογία ουροποιητικού και ανδρικού αναπαραγωγικού συστήματος.', 15, 'Κτίριο Β - 3ος Όροφος', NULL),
('Νεφρολογία', 'Νεφρικές παθήσεις και αιμοκάθαρση. Περιλαμβάνει μονάδα dialysis.', 15, 'Κτίριο Γ - 3ος Όροφος', NULL),
('Ογκολογία', 'Διάγνωση και θεραπεία κακοηθών νεοπλασμάτων. Περιλαμβάνει μονάδα χημειοθεραπείας.', 25, 'Κτίριο Δ - 1ος Όροφος', NULL),
('Παιδιατρική', 'Νοσηλεία παιδιών ηλικίας 0-14 ετών. Περιλαμβάνει ΜΕΝΝ (Μονάδα Νεογνών).', 30, 'Κτίριο Δ - 2ος Όροφος', NULL),
('Μαιευτική-Γυναικολογία', 'Τοκετοί, γυναικολογικές επεμβάσεις και περιγεννητική φροντίδα.', 25, 'Κτίριο Δ - 3ος Όροφος', NULL),
('Ψυχιατρική', 'Νοσηλεία ασθενών με οξείες και χρόνιες ψυχικές διαταραχές.', 20, 'Κτίριο Ε - 1ος Όροφος', NULL),
('ΜΕΘ', 'Μονάδα Εντατικής Θεραπείας. Νοσηλεία βαρέως πασχόντων ασθενών με πολυοργανική υποστήριξη.', 12, 'Κτίριο Α - Υπόγειο 1', NULL);
